<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { useRouter } from "vue-router"; import type { PublishedGameSummary } from "@arcade/shared"; import { getPortalGames } from "../services/api"; import { clearRecent, readFavorites, readRecent, removeFavorite, toggleFavorite, rememberRecent } from "../services/portalStorage"; import GameGrid from "../components/portal/GameGrid.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue";
const router = useRouter(); const all = ref<PublishedGameSummary[]>([]); const favorites = ref<string[]>(readFavorites().values); const recent = ref<string[]>(readRecent().values); const loading = ref(true); const favoriteGames = computed(() => all.value.filter((game) => favorites.value.includes(game.slug))); const recentGames = computed(() => recent.value.map((slug) => all.value.find((game) => game.slug === slug)).filter((game): game is PublishedGameSummary => Boolean(game)));
async function load(): Promise<void> { try { all.value = (await getPortalGames()).data; } finally { loading.value = false; } } function favorite(slug: string): void { favorites.value = toggleFavorite(slug).values; } function play(slug: string): void { rememberRecent(slug); void router.push(`/zh/game/${slug}/play`); } function clear(): void { clearRecent(); recent.value = []; } onMounted(() => { void load(); document.title = "我的收藏｜星屿游廊"; });
</script><template><div class="portal-page"><section class="portal-page-heading"><span class="portal-eyebrow">YOUR SHELF</span><h1>我的收藏</h1><p>游客收藏与最近玩仅保存版本化 slug 列表，不保存 token 或完整游戏存档。</p></section><ContentStatePanel v-if="loading" kind="loading" title="正在读取你的游戏架" message="收藏内容只在当前浏览器中保存。" /><template v-else><section class="portal-section"><div class="portal-section-heading"><div><span class="portal-eyebrow">收藏夹</span><h2>喜欢的游戏</h2></div><span>{{ favoriteGames.length }} 款</span></div><ContentStatePanel v-if="!favoriteGames.length" kind="empty" title="还没有收藏" message="在游戏卡片或详情页点击星标，留住喜欢的作品。" action="去游戏大厅" @action="router.push('/zh/games')" /><GameGrid v-else :games="favoriteGames" :favorites="favorites" @favorite="favorite" @play="play" /></section><section class="portal-section"><div class="portal-section-heading"><div><span class="portal-eyebrow">最近打开</span><h2>最近玩过</h2></div><button class="text-link-button" type="button" @click="clear">清空记录</button></div><ContentStatePanel v-if="!recentGames.length" kind="empty" title="还没有最近记录" message="开始一款游戏后，它会出现在这里。" /><GameGrid v-else :games="recentGames" :favorites="favorites" @favorite="favorite" @play="play" /></section></template></div></template>
